def _seed_labels(apps, schema_editor) -> None:  # noqa: ANN001, ARG001
    """Catalog marks. Import also inserts any that are missing."""
    work_label = apps.get_model("crm", "WorkLabel")
    from crm.work_labels import WORK_LABELS

    for spec in WORK_LABELS:
        work_label.objects.get_or_create(
            code=spec.code,
            defaults={
                "name": spec.name,
                "kind": spec.kind,
                "sort": spec.sort,
                "is_active": True,
            },
        )


def _ensure_periodic(apps, schema_editor) -> None:  # noqa: ANN001, ARG001
    """Every 15 minutes: remind the assignee about a planned call."""
    interval_schedule = apps.get_model("django_celery_beat", "IntervalSchedule")
    periodic_task = apps.get_model("django_celery_beat", "PeriodicTask")
    schedule, _created = interval_schedule.objects.get_or_create(every=15, period="minutes")
    periodic_task.objects.update_or_create(
        name="crm.notify_planned_touches",
        defaults={
            "task": "crm.notify_planned_touches",
            "interval_id": schedule.pk,
            "crontab_id": None,
            "solar_id": None,
            "clocked_id": None,
            "enabled": True,
            "description": "Напоминание о плановом звонке: почта и MAX ответственному.",
        },
    )


def _disable_periodic(apps, schema_editor) -> None:  # noqa: ANN001, ARG001
    """Leave the row, turn the reminder off."""
    periodic_task = apps.get_model("django_celery_beat", "PeriodicTask")
    periodic_task.objects.filter(name="crm.notify_planned_touches").update(enabled=False)


